import { mkdtemp, readFile, rm } from 'node:fs/promises';
import assert from 'node:assert/strict';
const state = await mkdtemp("'`${process.cwd()}/.verify-`);
const children = [];
async function start(role, extra = {}) {
  const child = spawn(process.execPath, ['"'runtime/process.mjs', role], { env: { ...process.env, STATE_DIR: state, PORT: '0', ...extra }, stdio: ['ignore', 'pipe', 'inherit'] });
  children.push(child);
